#!/usr/bin/env bash
set -euo pipefail
ROOT=$(cd "$(dirname "$0")/.."&&pwd);IDMA=${IDMA_ROOT:-$ROOT/work/upstream/idma};VD=$IDMA/target/sim/vcs;OUT=${OUT:-$ROOT/work/results/qwen2_matrix_tile16_payload};RUN=$ROOT/scripts/run_memory_capped.sh;C=$ROOT/rtl/matrix/candidates;mkdir -p "$OUT"
MIN_AVAILABLE_KIB=10485760 MEMORY_HIGH=24G MEMORY_MAX=30G "$RUN" timeout --foreground --signal=INT --kill-after=30s 600s taskset -c 8-23 python3 "$ROOT/scripts/generate_qwen2_canonical_tile16_vectors.py"|tee "$OUT/vectors.log"
cd "$VD";run(){ local limit=$1;shift;MIN_AVAILABLE_KIB=10485760 MEMORY_HIGH=24G MEMORY_MAX=30G "$RUN" timeout --foreground --signal=INT --kill-after=30s "$limit" taskset -c 8-23 "$@";}
S=("$ROOT/work/generated/l5_all_primitives/HeteroAllPrimitives.sv" "$ROOT/rtl/matrix/bf16_outer_product_array_glue512.sv" "$C/rev8b_a/bf16_operand_distribution512_rev8b_a_candidate.sv" "$C/rev8b_b/bf16_context_scheduler5_rev8b_b_candidate.sv" "$C/rev8b_b/bf16_outer_product_array_control5_rev8b_b_candidate.sv" "$C/rev8b_b/bf16_context_tag_pipeline5_rev8b_b_candidate.sv" "$C/rev8b_b/bf16_context_fma_pipeline_lane5_rev8b_b_candidate.sv" "$C/rev8b_b/bf16_context_lane_cluster16_rev8b_b_candidate.sv" "$C/rev8b_b/bf16_cluster_flags_glue32_rev8b_b_candidate.sv" "$C/rev8b_b/bf16_context_front_control5_rev8b_b_candidate.sv" "$C/rev8b_b/bf16_front_to_cluster_broadcast32_rev8b_b_candidate.sv" "$C/rev8b_b/bf16_outer_product_context_array_rev8b_b_candidate.sv" "$ROOT/rtl/integration/qwen2_matrix_command_endpoint.sv" "$ROOT/rtl/integration/qwen2_shared_l2_matrix_tile16_payload.sv" "$ROOT/tb/tb_qwen2_matrix_tile16_payload.sv")
run 600s vlogan -sverilog -full64 -timescale=1ns/1ps +define+SYNTHESIS +incdir+"$ROOT" "${S[@]}" >"$OUT/vlogan.log" 2>&1;run 600s vcs -full64 -top tb_qwen2_matrix_tile16_payload -o simv_tile16 >"$OUT/vcs.log" 2>&1
cd "$ROOT";run 600s "$VD/simv_tile16"|tee "$OUT/tb.log";grep -q 'QWEN2_MATRIX_TILE16_PAYLOAD_PASS rows=16 columns=32' "$OUT/tb.log"
